const fetch = async (url, opts = {}) => {
  const res = await this.helpers.httpRequest({ url: String(url), method: opts.method || 'GET', headers: opts.headers, body: opts.body, returnFullResponse: true, ignoreHttpStatusErrors: true, encoding: 'text', json: false });
  const text = typeof res.body === 'string' ? res.body : JSON.stringify(res.body);
  return { ok: res.statusCode < 400, status: res.statusCode, headers: res.headers, text: async () => text, json: async () => JSON.parse(text) };
};
